// 조합식 태그 판별 (공백 포함 여부로 판단 - 기존 + 포함 태그도 호환)
function isComboTag(tag) {
  if (!tag) return false;
  // 기존 "+" 또는 새로운 공백 형식 모두 지원
  return tag.includes("+") || (tag.includes(" ") && COMBO_TAG_TRAITS.some(t => tag.startsWith(t)));
}

