      { const s = tok.replace(/(이라는|으로|에서|에게|한테|이라|에는)$/, ""); if (s.length >= 2) tok = s; } // 흔한 다글자 조사 꼬리
      { const s = tok.replace(/(의|는|은|이|가|을|를|에|도|로|와|과|만|랑|들)$/, ""); if (s.length >= 2) tok = s; } // 흔한 단글자 조사/복수 꼬리
      if (tok.length < 2 || tok.length > 7) continue;
