/* =========================================================
   유틸리티 함수
   ========================================================= */
function parsePlatforms(p) {
  try { const arr = JSON.parse(p || "[]"); return Array.isArray(arr) ? arr : []; }
  catch { return []; }
}

// 🆕 플랫폼 요약 표시 (첫 번째만 + 나머지 개수)
function formatPlatformShort(platforms) {
  const plats = typeof platforms === "string" ? parsePlatforms(platforms) : (platforms || []);
  if (!plats.length) return "-";
  if (plats.length === 1) return plats[0];
  return `${plats[0]} +${plats.length - 1}`;
}

// 🆕 v7.31.0: 일괄추가 입력 파서 — 한 줄에 하나씩(기존)뿐 아니라 '티어표 내보내기' 텍스트도 수용.
//   • "🏆 …" 머리말, "【B+티어】" 섹션 헤더, 빈 줄 무시
//   • "  1. 제목" 같은 번호 접두( N. / N) )를 떼고 제목만 추출
//   • 중복 제거(순서 유지)
function parseBatchTitles(text) {
  const out = [];
  const seen = new Set();
  for (const raw of String(text == null ? "" : text).split("\n")) {
    let s = raw.trim();
    if (!s) continue;
    if (s.startsWith("🏆")) continue;            // 티어표 머리말
    if (/^【.*】$/.test(s)) continue;             // 【…티어】 섹션 헤더
    s = s.replace(/^\d+\s*[.)]\s*/, "").trim();   // "1. 제목" / "1) 제목" → "제목"
    if (!s || seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

function getWinRate(wins, losses) {
  const total = (wins || 0) + (losses || 0);
  return total > 0 ? ((wins || 0) / total * 100).toFixed(1) : "-";
}

/**
 * 🛡️ v3.5.6: 안전한 URL 오픈 (빈/잘못된 URL → crash 방지)
 */
function safeOpenURL(url) {
  if (!url || typeof url !== "string" || !url.trim()) {
    Alert.alert("알림", "링크가 등록되지 않았습니다.");
    return;
  }
  const trimmed = url.trim();
  Linking.canOpenURL(trimmed).then(supported => {
    if (supported) {
      Linking.openURL(trimmed);
    } else {
      // 스킴이 없으면 https:// 붙여서 시도
      const withScheme = trimmed.startsWith("http") ? trimmed : `https://${trimmed}`;
      Linking.openURL(withScheme).catch(() => {
        Alert.alert("오류", "링크를 열 수 없습니다: " + trimmed);
      });
    }
  }).catch(() => {
    Linking.openURL(trimmed).catch(() => {
      Alert.alert("오류", "링크를 열 수 없습니다.");
    });
  });
}

// 🆕 등록 후 한달 이내인지 확인
function isNewNovel(createdAt) {
  if (!createdAt) return false;
  const oneMonthAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
  return createdAt > oneMonthAgo;
}

// 🏷️ 장르 파싱 헬퍼 (JSON 배열 또는 단일 문자열 → 배열)
function parseGenreArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed;
    return [parsed];
  } catch {
    return value ? [value] : [];
  }
}

// 🏷️ 장르 첫 번째 값 가져오기 (카드 표시용)
function getFirstGenre(value) {
  const arr = parseGenreArray(value);
  return arr.length > 0 ? arr[0] : "";
}

/* =========================================================
   💬 v3.5.4~v3.5.6: 인상깊은 문장 다중 지원 유틸리티
   - 하위 호환: 기존 단일 문자열 → ["문자열"] 변환
   - 하위 호환: 기존 JSON 배열 '["quote1","quote2"]' 파싱 지원
   - v3.5.6: 새 형식 @ 구분자 '문장1 @ 문장2' (쉼표 충돌 방지)
   ========================================================= */
/**
 * 이미지 인용구 판별
 */
function isImageQuote(q) {
  return q && typeof q === "object" && q.type === "image" && !!q.uri;
}

// ─────────────────────────────────────────────────────────────────────────────
// 🆕 v7.8.0: 명대사 텍스트 서식 (직접 입력 문장에 폰트/크기/자간/행간/색/배경 지정)
//   - 평문 문자열(string) = 서식 없음(레거시/기본). 서식 지정 시 { type:"text", text, style } 객체로 승격.
//   - 이미지 quote({type:"image"})는 기존 그대로.
// ─────────────────────────────────────────────────────────────────────────────
const QUOTE_FONTS = [
  { key: "system",        label: "기본",     regular: null,                       bold: null },
  { key: "nanumGothic",   label: "나눔고딕", regular: "NanumGothic_400Regular",   bold: "NanumGothic_700Bold" },
  { key: "nanumMyeongjo", label: "나눔명조", regular: "NanumMyeongjo_400Regular", bold: "NanumMyeongjo_700Bold" },
  { key: "gowunBatang",   label: "고운바탕", regular: "GowunBatang_400Regular",   bold: "GowunBatang_700Bold" },
  { key: "jua",           label: "주아",     regular: "Jua_400Regular",           bold: "Jua_400Regular" },
];
const QUOTE_FONT_MAP = Object.fromEntries(QUOTE_FONTS.map(f => [f.key, f]));
// 텍스트색/배경색 스와치 (배경은 "없음"=null 포함)
const QUOTE_TEXT_COLORS = [null, "#111827", "#ffffff", "#ef4444", "#f59e0b", "#22c55e", "#3b82f6", "#8b5cf6", "#ec4899"];
const QUOTE_BG_COLORS   = [null, "#111827", "#1f2937", "#fef3c7", "#fee2e2", "#dcfce7", "#dbeafe", "#f3e8ff", "#fce7f3"];
const QUOTE_SIZE_MIN = 12, QUOTE_SIZE_MAX = 40;
const QUOTE_LS_MIN = -2, QUOTE_LS_MAX = 12;          // 자간
const QUOTE_LH_MIN = 16, QUOTE_LH_MAX = 64;          // 행간
const DEFAULT_QUOTE_STYLE = { font: "system", size: 0, letterSpacing: null, lineHeight: 0, color: null, bg: null, bgImage: null, bold: false, italic: true, align: "center" };

function isTextQuote(q) {
  return (typeof q === "string") || (q && typeof q === "object" && q.type === "text");
}
function getQuoteText(q) {
  if (typeof q === "string") return q;
  if (q && typeof q === "object" && q.type === "text") return q.text || "";
  return "";
}
// 🔤 v7.28.24 검색용: 작품 명대사에서 검색 가능한 텍스트 모음(평문/서식 텍스트 + 이미지 OCR + 캡션).
//   이미지 명대사도 OCR(ocrText)하면 이 텍스트에 포함되어 검색됨.
function getNovelQuoteSearchText(n) {
  const raw = (n && n.memorable_quote) ? String(n.memorable_quote) : "";
  if (!raw.trim()) return "";
  try {
    const parts = [];
    for (const q of parseQuotes(raw)) {
      if (typeof q === "string") { if (q.trim()) parts.push(q); }
      else if (q && typeof q === "object") {
        if (q.type === "text" && q.text) parts.push(q.text);
        if (q.ocrText) parts.push(q.ocrText);
        if (q.caption) parts.push(q.caption);
      }
    }
    return parts.join(" ");
  } catch { return ""; }
}
function getQuoteStyle(q) {
  return (q && typeof q === "object" && q.type === "text" && q.style && typeof q.style === "object") ? q.style : null;
}
function resolveQuoteFontFamily(fontKey, bold) {
  const f = QUOTE_FONT_MAP[fontKey];
  if (!f || !f.regular) return undefined; // 시스템 기본 → fontFamily 미지정
  return bold ? (f.bold || f.regular) : f.regular;
}
// 스타일이 전부 기본값이면 평문 문자열로 다운그레이드 가능 (저장 컴팩트 + 하위호환)
function quoteStyleIsDefault(s) {
  if (!s || typeof s !== "object") return true;
  return (!s.font || s.font === "system") && !(s.size > 0) && (s.letterSpacing == null)
    && !(s.lineHeight > 0) && !s.color && !s.bg && !s.bgImage && !s.bold
    && (s.italic === undefined || s.italic === true) && (!s.align || s.align === "center");
}
// 🔧 v7.15.0: 두 명대사 서식이 (표시상) 동일한지 — 개별 서식이 프리셋과 같아지면 평문으로 재연결(프리셋 추종) 판단용
function quoteStylesEqual(a, b) {
  const norm = (s) => {
    const v = s || {};
    return [
      (v.font && v.font !== "system") ? v.font : "system",
      !!v.bold,
      v.italic === false ? "f" : "t",
      v.size > 0 ? v.size : 0,
      v.lineHeight > 0 ? v.lineHeight : 0,
      v.letterSpacing != null ? v.letterSpacing : "n",
      v.color || "",
      v.bg || "",
      v.bgImage || "",
      v.align || "center",
    ].join("|");
  };
  return norm(a) === norm(b);
}
// 최종 RN Text 스타일 = 표면별 auto 기본값 + 사용자 서식 오버라이드
function resolveQuoteTextStyle(style, auto) {
  const s = style || {};
  const fam = resolveQuoteFontFamily(s.font || "system", !!s.bold);
  const effSize = (s.size > 0) ? s.size : auto.size;
  const out = {
    fontSize: effSize,
    lineHeight: (s.lineHeight > 0) ? s.lineHeight : (s.size > 0 ? Math.round(effSize * 1.4) : auto.lineHeight),
    letterSpacing: (s.letterSpacing != null) ? s.letterSpacing : auto.letterSpacing,
    color: s.color || auto.color,
    textAlign: s.align || auto.textAlign || "center",
    fontStyle: ((s.italic != null) ? s.italic : (auto.fontStyle === "italic")) ? "italic" : "normal",
  };
  if (fam) {
    out.fontFamily = fam;                   // 커스텀 폰트: weight는 family에 내장
    // 🔧 v7.13.8: 커스텀 한글 폰트는 italic 변형 파일이 없어, fontStyle:"italic"를 함께 주면
    //   Android가 폰트 매칭에 실패해 family를 통째로 무시(시스템 폴백)한다. → 커스텀 폰트엔
    //   italic 강제 해제(글꼴 자체가 적용되도록). 칩이 되고 미리보기가 안 되던 원인.
    out.fontStyle = "normal";
  } else {
    out.fontWeight = s.bold ? "700" : (auto.fontWeight || "400");
  }
  return out;
}
// 배경색 명도에 따라 가독성 좋은 글자색(흰/검) 반환 — 카드 헤더/푸터/본문 대비용
function quoteContrastColor(hex) {
  if (!hex || typeof hex !== "string") return "#111827";
  let h = hex.replace("#", "");
  if (h.length === 3) h = h.split("").map(c => c + c).join("");
  if (h.length < 6) return "#111827";
  const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
  if ([r, g, b].some(n => Number.isNaN(n))) return "#111827";
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum > 0.6 ? "#111827" : "#ffffff";
}

/* =========================================================
   🆕 v7.8.1: AutoFitQuoteText — 명대사 자동 크기(맞춤)
   - fixedSize>0 이면 그대로, 0(자동)이면 컨테이너 높이에 맞게 폰트 축소(잘림 방지)
   - onLayout으로 가용 높이 측정 + onTextLayout으로 실제 줄 높이 측정 → 비례 축소(1~2패스 수렴)
   - ❝❞ 따옴표를 내부에 포함해 예약 높이를 반영
   ========================================================= */
// 🆕 v7.23.0: 명대사 자동 글자맞춤 공용 훅 — AutoFitQuoteText/AwardQuoteText 중복(3중 복제) 제거.
//   '축소 단일 방향'(v7.20.2): startSize에서 시작, budget 초과 시에만 줄임(단조 감소 → 진동 수학적 불가).
//   budget<=0이면 비활성(고정 크기 모드). resetKey/startSize/fontKey 변경 시 리셋 후 재축소
//   (fontKey=글꼴/굵기/자간 fingerprint → 사용자가 명대사 폰트를 바꾸면 재적합). attemptsRef(≤40) 안전망.
function useAutoFitFontSize({ resetKey, startSize, minSize = 11, budget, fontKey }) {
  const [size, setSize] = useState(startSize > 0 ? startSize : 18);
  const measRef = useRef(0);     // 마지막 측정 높이
  const attemptsRef = useRef(0); // 축소 시도 횟수(무한 루프 안전망)
  useEffect(() => {
    measRef.current = 0;
    attemptsRef.current = 0;
    setSize(startSize > 0 ? startSize : 18);
  }, [resetKey, startSize, fontKey]);
  const fit = (h) => {
    if (!(budget > 0) || h <= 0) return; // 비활성(고정) 또는 미측정
    if (h <= budget) return;             // 들어감 → 정지(절대 키우지 않음 = 진동 없음)
    setSize(prev => {
      if (prev <= minSize) return prev;  // 더 줄일 수 없음
      // 근소 초과는 1씩, 큰 초과는 비례 점프 — 어느 쪽이든 '현재보다 작게' 강제.
      let target = (h <= budget * 1.18) ? prev - 1 : Math.floor(prev * (budget / h) * 0.98);
      target = Math.max(minSize, Math.min(prev - 1, target));
      if (target !== prev && attemptsRef.current < 40) { attemptsRef.current += 1; return target; }
      return prev;
    });
  };
  const onTextLayout = (e) => {
    const lines = e?.nativeEvent?.lines;
    if (!lines || !lines.length) return;
    let h = 0;
    for (const ln of lines) h += (ln.height || 0);
    if (h <= 0) return;
    measRef.current = h;
    fit(h);
  };
  // budget(가용 높이/한도) 늦은 측정·변동 시 마지막 높이로 재적합(축소 방향만)
  useEffect(() => { if (measRef.current > 0) fit(measRef.current); }, [budget]); // eslint-disable-line react-hooks/exhaustive-deps
  return { size, onTextLayout };
}

const AutoFitQuoteText = memo(({ text, baseStyle, fixedSize, userLineHeight, maxSize = 23, minSize = 11, marksColor }) => {
  const [avail, setAvail] = useState(0);
  // fixedSize>0 이면 자동맞춤 비활성(budget 0). 자동이면 가용높이 - ❝❞/여백 80 예약.
  const budget = fixedSize > 0 ? 0 : (avail > 0 ? avail - 80 : 0);
  const fontKey = `${baseStyle?.fontFamily || ""}|${baseStyle?.fontWeight || ""}|${baseStyle?.letterSpacing || ""}`;
  const { size, onTextLayout } = useAutoFitFontSize({
    resetKey: text, startSize: fixedSize > 0 ? fixedSize : maxSize, minSize, budget, fontKey,
  });
  const lh = userLineHeight > 0 ? userLineHeight : Math.round(size * 1.45);
  return (
    <View
      style={{ flex: 1, width: "100%", justifyContent: "center" }}
      onLayout={(e) => { const h = e.nativeEvent.layout.height; if (h > 0 && Math.abs(h - avail) > 1) setAvail(h); }}
    >
      <Text style={{ fontSize: 28, color: marksColor, textAlign: "center", opacity: 0.4, marginBottom: 2 }}>❝</Text>
      <Text style={[baseStyle, { fontSize: size, lineHeight: lh }]} onTextLayout={onTextLayout}>{text}</Text>
      <Text style={{ fontSize: 28, color: marksColor, textAlign: "center", opacity: 0.4, marginTop: 2 }}>❞</Text>
    </View>
  );
});

// 🆕 v7.9.0: 개별 커스텀이 없으면 전역 기본 프리셋을 적용 (둘 다 없으면 null=내장 자동)
// 🔙 v7.16.2: v7.15.0 '병합' 원복 — 개별 서식이 있으면 그대로(교체) 사용. 병합 도입 후 명언탭에서
//   서식 미적용/지연·꾸미기 무반응 등 회귀가 보고되어 세션 이전(안정) 동작으로 복원. (병합은 추후
//   디바이스 검증과 함께 안전하게 재시도.)
function effectiveQuoteStyle(individualStyle, defaultStyle) {
  if (individualStyle && !quoteStyleIsDefault(individualStyle)) return individualStyle;
  if (defaultStyle && !quoteStyleIsDefault(defaultStyle)) return defaultStyle;
  return null;
}

function parseQuotes(val) {
  if (!val || typeof val !== "string" || !val.trim()) return [];
  const trimmed = val.trim();
  // 하위호환: 기존 JSON 배열 형식 지원 (텍스트 + 이미지 + 서식 텍스트 객체)
  if (trimmed.startsWith("[")) {
    try {
      const arr = JSON.parse(trimmed);
      if (Array.isArray(arr)) return arr.filter(q =>
        (typeof q === "string" && q.trim()) ||
        (q && typeof q === "object" && q.type === "image" && q.uri) ||
        (q && typeof q === "object" && q.type === "text" && typeof q.text === "string" && q.text.trim())
      );
      return [];
    } catch { /* JSON 파싱 실패 시 아래로 계속 */ }
  }
  // 🔧 v6.0.1: @ 구분자 기반 다중 문장 파싱 — 이메일/핸들러 패턴 보호
  // 구분자 @: 앞뒤에 공백이 1개 이상 있어야 구분자로 인식 (user@email.com 보호)
  // 레거시 호환: 공백 없는 @ 단독 사용("문장1@문장2")도 지원
  if (trimmed.includes("@")) {
    // 공백 있는 @ 먼저 시도 (안전한 구분자)
    if (/\s@\s/.test(trimmed)) {
      return trimmed.split(/\s+@\s+/).map(q => q.trim()).filter(Boolean);
    }
    // 레거시 폴백: @가 단어 사이에 없을 때만 (이메일 패턴 아닐 때)
    if (!/\w@\w/.test(trimmed)) {
      return trimmed.split("@").map(q => q.trim()).filter(Boolean);
    }
  }
  return [trimmed];
}

function serializeQuotes(arr) {
  if (!arr || arr.length === 0) return "";
  // 서식 텍스트 객체 정규화: 빈 스타일이면 평문 문자열로 다운그레이드
  const norm = arr.map(q => {
    if (q && typeof q === "object" && q.type === "text") {
      const t = (q.text || "").trim();
      if (!t) return null;
      if (quoteStyleIsDefault(q.style)) return t; // 평문화 (저장 컴팩트)
      const o = { type: "text", text: t, style: q.style };
      if (q.caption) o.caption = q.caption;
      return o;
    }
    return q;
  }).filter(q => q != null);
  // 이미지 또는 서식 텍스트 객체가 있으면 JSON 직렬화
  const hasComplex = norm.some(q => isImageQuote(q) || (q && typeof q === "object" && q.type === "text"));
  if (hasComplex) {
    const cleaned = norm.filter(q =>
      isImageQuote(q) ||
      (q && typeof q === "object" && q.type === "text") ||
      (typeof q === "string" && q.trim())
    );
    return cleaned.length > 0 ? JSON.stringify(cleaned) : "";
  }
  // 텍스트 평문 전용: 기존 @ 구분자 로직
  const cleaned = norm.filter(q => typeof q === "string" && q.trim()).map(q => q.trim());
  if (cleaned.length === 0) return "";
  // 🔧 v7.49.20: quote 텍스트에 '@'가 있으면 ' @ ' 구분자/레거시 @ 분할(parseQuotes)로 round-trip 시 한 문장이 여러 개로
  //   분열되는 데이터 손상 → JSON 경로로 직렬화(parseQuotes가 '['로 시작하면 JSON 우선 파싱하므로 무손실).
  if (cleaned.some(q => q.includes("@"))) return JSON.stringify(cleaned);
  if (cleaned.length === 1) return cleaned[0]; // 하위 호환: 1개면 단일 문자열
  return cleaned.join(" @ ");
}

/* =========================================================
   🆕 v7.8.0: 명대사 텍스트 서식 편집기 (QuoteStyleEditor)
   - 폰트/크기/자간/행간/글자색/배경색/배경이미지/볼드/이탤릭/정렬
   - style 객체를 받아 onChange(newStyle)로 통지 (상위가 quote 항목에 반영)
   - onPickBgImage: 비동기 이미지 선택 → 저장된 uri 반환(없으면 null)
   ========================================================= */
const QuoteStyleEditor = memo(({ style, text, onChange, onPickBgImage, onClearBgImage, theme, isDark, busy }) => {
  const C = theme;
  const s = { ...DEFAULT_QUOTE_STYLE, ...(style || {}) };
  const set = (patch) => onChange({ ...s, ...patch });
  const previewAuto = { size: 20, lineHeight: 28, letterSpacing: 0.3, color: C.text, textAlign: "center", fontStyle: "italic", fontWeight: "500" };
  const eff = resolveQuoteTextStyle(s, previewAuto);
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  const btnStyle = { width: 34, height: 30, borderRadius: 7, backgroundColor: C.chip, alignItems: "center", justifyContent: "center" };
  const stepRow = (label, display, onDec, onInc, onAuto) => (
    <View style={{ flexDirection: "row", alignItems: "center", marginTop: 8 }}>
      <Text style={{ color: C.sub, fontSize: 12, width: 38 }}>{label}</Text>
      <TouchableOpacity onPress={onDec} style={btnStyle}><Text style={{ color: C.text, fontSize: 18, fontWeight: "800" }}>−</Text></TouchableOpacity>
      <Text style={{ color: C.text, fontSize: 13, fontWeight: "700", minWidth: 54, textAlign: "center" }}>{display}</Text>
      <TouchableOpacity onPress={onInc} style={btnStyle}><Text style={{ color: C.text, fontSize: 16, fontWeight: "800" }}>＋</Text></TouchableOpacity>
      <TouchableOpacity onPress={onAuto} style={{ marginLeft: 8, paddingHorizontal: 8, paddingVertical: 5, borderRadius: 6, backgroundColor: C.bg, borderWidth: 1, borderColor: C.line }}>
        <Text style={{ color: C.sub, fontSize: 11 }}>자동</Text>
      </TouchableOpacity>
    </View>
  );
  const swatch = (color, selected, onPress, isNone) => (
    <TouchableOpacity key={String(color)} onPress={onPress} style={{
      width: 26, height: 26, borderRadius: 13, marginRight: 6, marginBottom: 6,
      backgroundColor: isNone ? "transparent" : color,
      borderWidth: selected ? 3 : 1,
      borderColor: selected ? C.primary : (isNone ? C.sub : C.line),
      alignItems: "center", justifyContent: "center",
    }}>
      {isNone ? <Text style={{ color: C.sub, fontSize: 11 }}>⊘</Text> : null}
    </TouchableOpacity>
  );

  return (
    <View style={{ marginTop: 8, padding: 10, backgroundColor: C.bg, borderRadius: 10, borderWidth: 1, borderColor: C.line }}>
      {/* 미리보기 */}
      <View style={{ borderRadius: 10, overflow: "hidden", minHeight: 80, justifyContent: "center", backgroundColor: s.bg || C.card, marginBottom: 10, borderWidth: 1, borderColor: C.line }}>
        {s.bgImage ? (
          <>
            <ExpoImage source={{ uri: s.bgImage }} style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0 }} contentFit="cover" cachePolicy="memory-disk" />
            <View style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0, backgroundColor: "rgba(0,0,0,0.28)" }} />
          </>
        ) : null}
        <Text style={[{ paddingVertical: 14, paddingHorizontal: 12 }, eff]}>
          {(text && text.trim()) ? text : "미리보기 문장"}
        </Text>
      </View>

      {/* 폰트 */}
      <Text style={{ color: C.sub, fontSize: 12, marginBottom: 4 }}>글꼴</Text>
      <View style={{ flexDirection: "row", flexWrap: "wrap" }}>
        {QUOTE_FONTS.map(f => {
          const sel = (s.font || "system") === f.key;
          return (
            <TouchableOpacity key={f.key} onPress={() => set({ font: f.key })} style={{
              paddingHorizontal: 12, paddingVertical: 7, borderRadius: 8, marginRight: 6, marginBottom: 6,
              backgroundColor: sel ? C.primary : C.chip,
            }}>
              <Text style={{ color: sel ? "#fff" : C.text, fontSize: 13, fontWeight: "600", fontFamily: resolveQuoteFontFamily(f.key, false) }}>{f.label}</Text>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* 굵게/기울임/정렬 */}
      <View style={{ flexDirection: "row", flexWrap: "wrap", marginTop: 8, gap: 6 }}>
        <TouchableOpacity onPress={() => set({ bold: !s.bold })} style={{ paddingHorizontal: 12, paddingVertical: 7, borderRadius: 8, backgroundColor: s.bold ? C.primary : C.chip }}>
          <Text style={{ color: s.bold ? "#fff" : C.text, fontSize: 13, fontWeight: "800" }}>굵게</Text>
        </TouchableOpacity>
        <TouchableOpacity onPress={() => set({ italic: !s.italic })} style={{ paddingHorizontal: 12, paddingVertical: 7, borderRadius: 8, backgroundColor: s.italic ? C.primary : C.chip }}>
          <Text style={{ color: s.italic ? "#fff" : C.text, fontSize: 13, fontStyle: "italic" }}>기울임</Text>
        </TouchableOpacity>
        {["left", "center", "right"].map(al => (
          <TouchableOpacity key={al} onPress={() => set({ align: al })} style={{ paddingHorizontal: 12, paddingVertical: 7, borderRadius: 8, backgroundColor: (s.align || "center") === al ? C.primary : C.chip }}>
            <Text style={{ color: (s.align || "center") === al ? "#fff" : C.text, fontSize: 13 }}>{al === "left" ? "왼쪽" : al === "center" ? "가운데" : "오른쪽"}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* 크기/자간/행간 */}
      {stepRow("크기", s.size > 0 ? `${s.size}` : "자동",
        () => set({ size: clamp((s.size > 0 ? s.size : 20) - 1, QUOTE_SIZE_MIN, QUOTE_SIZE_MAX) }),
        () => set({ size: clamp((s.size > 0 ? s.size : 20) + 1, QUOTE_SIZE_MIN, QUOTE_SIZE_MAX) }),
        () => set({ size: 0 }))}
      {stepRow("자간", s.letterSpacing != null ? `${s.letterSpacing}` : "자동",
        () => set({ letterSpacing: clamp(Math.round(((s.letterSpacing != null ? s.letterSpacing : 0) - 0.5) * 10) / 10, QUOTE_LS_MIN, QUOTE_LS_MAX) }),
        () => set({ letterSpacing: clamp(Math.round(((s.letterSpacing != null ? s.letterSpacing : 0) + 0.5) * 10) / 10, QUOTE_LS_MIN, QUOTE_LS_MAX) }),
        () => set({ letterSpacing: null }))}
      {stepRow("행간", s.lineHeight > 0 ? `${s.lineHeight}` : "자동",
        () => set({ lineHeight: clamp((s.lineHeight > 0 ? s.lineHeight : 28) - 2, QUOTE_LH_MIN, QUOTE_LH_MAX) }),
        () => set({ lineHeight: clamp((s.lineHeight > 0 ? s.lineHeight : 28) + 2, QUOTE_LH_MIN, QUOTE_LH_MAX) }),
        () => set({ lineHeight: 0 }))}

      {/* 글자색 */}
      <Text style={{ color: C.sub, fontSize: 12, marginTop: 10, marginBottom: 4 }}>글자색</Text>
      <View style={{ flexDirection: "row", flexWrap: "wrap" }}>
        {QUOTE_TEXT_COLORS.map(col => swatch(col, (s.color || null) === col, () => set({ color: col }), col === null))}
      </View>

      {/* 배경색 */}
      <Text style={{ color: C.sub, fontSize: 12, marginTop: 6, marginBottom: 4 }}>배경색</Text>
      <View style={{ flexDirection: "row", flexWrap: "wrap" }}>
        {QUOTE_BG_COLORS.map(col => swatch(col, (s.bg || null) === col, () => set({ bg: col }), col === null))}
      </View>

      {/* 배경 이미지 */}
      <Text style={{ color: C.sub, fontSize: 12, marginTop: 6, marginBottom: 4 }}>배경 이미지</Text>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
        <TouchableOpacity
          disabled={busy}
          onPress={async () => {
            if (busy || !onPickBgImage) return;
            const uri = await onPickBgImage();
            if (uri) {
              // 🔧 v7.12.0: 교체 시 이전 배경이미지 파일 정리 등록 — 이전엔 '변경'으로 새 이미지를
              //   고르면 옛 파일이 어떤 추적 ref에도 안 들어가 영구 고아로 남았음. onClearBgImage가
              //   컨텍스트별로 올바르게 처리(등록/프리셋=즉시삭제, 편집/예정/빠른수정=저장 시 삭제).
              const prev = s.bgImage;
              if (prev && prev !== uri && onClearBgImage) onClearBgImage(prev);
              set({ bgImage: uri });
            }
          }}
          style={{ paddingHorizontal: 12, paddingVertical: 8, borderRadius: 8, backgroundColor: C.chip, opacity: busy ? 0.5 : 1 }}
        >
          <Text style={{ color: C.text, fontSize: 13, fontWeight: "600" }}>🖼️ {s.bgImage ? "변경" : "선택"}</Text>
        </TouchableOpacity>
        {s.bgImage ? (
          <TouchableOpacity
            onPress={() => { if (onClearBgImage) onClearBgImage(s.bgImage); set({ bgImage: null }); }}
            style={{ paddingHorizontal: 12, paddingVertical: 8, borderRadius: 8, backgroundColor: C.bg, borderWidth: 1, borderColor: C.line }}
          >
            <Text style={{ color: C.warn, fontSize: 13, fontWeight: "600" }}>제거</Text>
          </TouchableOpacity>
        ) : null}
      </View>

      <Text style={{ color: C.sub, fontSize: 11, marginTop: 10, lineHeight: 16 }}>
        💡 크기 "자동"은 💬명언 카드 높이에 맞춰 글자가 잘리지 않게 자동 조절됩니다. 직접 크기를 정하면 그 값으로 고정됩니다.
      </Text>
    </View>
  );
});

/**
 * 🛡️ v3.5.6: 소설 객체 숫자 필드 정규화
 * DB에서 직접 조회한 row의 null/undefined 필드를 안전한 기본값으로 변환
 * → .toFixed(), Math.round() 등에서 크래시 방지
 */
function normalizeNovel(r) {
  if (!r) return r;
  return {
    ...r,
    rating: Number(r.rating) || 1500,
    rd: Number(r.rd) || 350,
    wins: Number(r.wins) || 0,
    losses: Number(r.losses) || 0,
    match_count: Number(r.match_count) || 0,
    read_count: Number(r.read_count) || 0,
    reread_count: r.reread_count != null ? Number(r.reread_count) : 1,
    pinned: Number(r.pinned) || 0,
    match_ban: Number(r.match_ban) || 0, // 🚫 v7.6.0 (포트 v3.16.0)
  };
}

/* =========================================================
   🔧 v7.6.0 (포트 v3.12.0): YearStepper — 연재 연도 입력
   - +/- 1년, 길게 누르면 0(미설정), ✕ 버튼으로 명시적 리셋
   ========================================================= */
const YearStepper = memo(({ label, value, onChange, isDark }) => {
  const displayValue = value > 0 ? String(value) : "미설정";
  const currentYear = new Date().getFullYear();
  const bg = isDark ? "#1a1a2e" : "#f8f9fa";
  const border = isDark ? "#333" : "#ddd";
  const textColor = isDark ? "#e0e0e0" : "#333";
  const subColor = isDark ? "#888" : "#999";
  const btnBg = isDark ? "#2a2a3e" : "#eee";

  const step = (delta) => {
    if (value === 0) {
      onChange(delta > 0 ? currentYear : currentYear - 1);
    } else {
      const next = value + delta;
      if (next >= 1990 && next <= 2099) onChange(next);
    }
  };

  return (
    <View style={{ marginBottom: 8 }}>
      {label && <Text style={{ color: subColor, fontSize: 12, marginBottom: 4 }}>{label}</Text>}
      <View style={{
        flexDirection: "row", alignItems: "center",
        backgroundColor: bg, borderRadius: 8, borderWidth: 1, borderColor: border,
        overflow: "hidden",
      }}>
        <TouchableOpacity
          onPress={() => step(-1)}
          style={{ paddingHorizontal: 14, paddingVertical: 10, backgroundColor: btnBg }}
        >
          <Text style={{ fontSize: 18, fontWeight: "700", color: textColor }}>−</Text>
        </TouchableOpacity>
        <TouchableOpacity
          onLongPress={() => onChange(0)}
          delayLongPress={500}
          style={{ flex: 1, alignItems: "center", paddingVertical: 10 }}
        >
          <Text style={{
            fontSize: 15, fontWeight: value > 0 ? "700" : "400",
            color: value > 0 ? textColor : subColor,
          }}>{displayValue}</Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={() => step(1)}
          style={{ paddingHorizontal: 14, paddingVertical: 10, backgroundColor: btnBg }}
        >
          <Text style={{ fontSize: 18, fontWeight: "700", color: textColor }}>+</Text>
        </TouchableOpacity>
        {value > 0 && (
          <TouchableOpacity
            onPress={() => onChange(0)}
            style={{ paddingHorizontal: 10, paddingVertical: 10, backgroundColor: btnBg, borderLeftWidth: 1, borderLeftColor: border }}
          >
            <Text style={{ fontSize: 14, fontWeight: "700", color: isDark ? "#e57373" : "#d32f2f" }}>✕</Text>
          </TouchableOpacity>
        )}
      </View>
    </View>
  );
});

/* =========================================================
   🖼️ 표지 라이브러리 시스템 (v3.4.7 - 레거시 FileSystem API)
   ========================================================= */

// 표지 저장 디렉토리 (레거시 API)
const COVER_DIR = FileSystem.documentDirectory + "covers/";

// 압축 설정 맵
const COMPRESSION_PRESETS = {
  original: { quality: 1.0, maxSize: null },        // 원본 유지
  light: { quality: 0.8, maxSize: 1200 },           // 가벼운 압축 (기본값)
  medium: { quality: 0.6, maxSize: 800 },           // 중간 압축
  heavy: { quality: 0.4, maxSize: 600 },            // 강한 압축
};

// 📷 명대사 이미지 압축 설정
const QUOTE_IMAGE_MAX_SIZE = 2048;  // 🔧 v7.24.6: 1600→2048px (확대·고DPI 풀폭에서 더 선명. 썸네일은 1600도 충분하나 확대 여유 확보. 기존 저장분 불변 — 재등록 시 적용)
const QUOTE_IMAGE_QUALITY = 1.0;    // 🔧 v7.24.6: JPEG 품질 0.9→1.0 (최고 품질 — 압축 아티팩트 최소화)
const QUOTE_IMAGE_MAX_COUNT = 50;   // 🔧 v7.19.1: 이미지 인용구 최대 개수 (30→50 확장. 순수 UI 가드 — 스키마/알고리즘 무의존. 백업 base64 캡은 3 유지 — buildUltraCompactBackup slice(0,3))

// 🎨 v3.8.0: 갤러리 이미지 설정
const GALLERY_IMAGE_MAX_COUNT = 20;    // 작품당 갤러리 이미지 최대 개수
const GALLERY_IMAGE_MAX_SIZE = 1200;   // 긴 변 최대 1200px
const GALLERY_IMAGE_QUALITY = 0.8;     // JPEG 품질 80%
const GALLERY_DIR = FileSystem.documentDirectory + "gallery/";

async function ensureGalleryDir() {
  try {
    const dirInfo = await FileSystem.getInfoAsync(GALLERY_DIR);
    if (!dirInfo.exists) {
      await FileSystem.makeDirectoryAsync(GALLERY_DIR, { intermediates: true });
    }
  } catch (e) {
    console.warn("ensureGalleryDir error:", e);
  }
}

/**
 * 🎨 갤러리 이미지 저장 (gallery 디렉토리)
 * compressAndSaveImage → COVER_DIR 임시 저장 → GALLERY_DIR로 이동
 */
async function saveGalleryImage(sourceUri, ext = "jpg") {
  try {
    const compressed = await compressAndSaveImage(sourceUri, GALLERY_IMAGE_MAX_SIZE, GALLERY_IMAGE_QUALITY, ext);
    if (compressed.error || !compressed.file_path) return compressed.error ? compressed : { error: "no file_path" };

    // COVER_DIR → GALLERY_DIR 이동
    await ensureGalleryDir();
    const fileName = compressed.file_path.split("/").pop();
    const destUri = GALLERY_DIR + fileName;
    try {
      await FileSystem.moveAsync({ from: compressed.file_path, to: destUri });
    } catch (moveErr) {
      // moveAsync 실패 시 COVER_DIR에 남은 파일 정리 (고아 방지)
      FileSystem.deleteAsync(compressed.file_path, { idempotent: true }).catch(() => {});
      return { error: "moveAsync: " + moveErr.message };
    }

    return { id: compressed.id, file_path: destUri, file_size: compressed.file_size };
  } catch (e) {
    return { error: "saveGalleryImage: " + e.message };
  }
}

/**
 * 이미지 포맷 감지 (expo-image-picker asset 기반)
 * asset.mimeType → fileName → uri 순서로 폴백
 * 지원: jpg, png, webp, gif, bmp, tiff, avif, heic/heif
 */
function getImageFormat(asset) {
  const mime = asset?.mimeType || "";
  if (mime.includes("webp"))  return { mime: "image/webp", ext: "webp" };
  if (mime.includes("png"))   return { mime: "image/png", ext: "png" };
  if (mime.includes("gif"))   return { mime: "image/gif", ext: "gif" };
  if (mime.includes("bmp"))   return { mime: "image/bmp", ext: "bmp" };
  if (mime.includes("tiff"))  return { mime: "image/tiff", ext: "tiff" };
  if (mime.includes("avif"))  return { mime: "image/avif", ext: "avif" };
  if (mime.includes("heic") || mime.includes("heif")) return { mime: "image/heic", ext: "heic" };
  const name = (asset?.fileName || asset?.uri || "").toLowerCase();
  if (name.endsWith(".webp")) return { mime: "image/webp", ext: "webp" };
  if (name.endsWith(".png"))  return { mime: "image/png", ext: "png" };
  if (name.endsWith(".gif"))  return { mime: "image/gif", ext: "gif" };
  if (name.endsWith(".bmp"))  return { mime: "image/bmp", ext: "bmp" };
  if (name.endsWith(".tiff") || name.endsWith(".tif")) return { mime: "image/tiff", ext: "tiff" };
  if (name.endsWith(".avif")) return { mime: "image/avif", ext: "avif" };
  if (name.endsWith(".heic") || name.endsWith(".heif")) return { mime: "image/heic", ext: "heic" };
  return { mime: "image/jpeg", ext: "jpg" };
}

// 표지 디렉토리 초기화 (레거시 API)
async function ensureCoverDir() {
  try {
    const dirInfo = await FileSystem.getInfoAsync(COVER_DIR);
    if (!dirInfo.exists) {
      await FileSystem.makeDirectoryAsync(COVER_DIR, { intermediates: true });
    }
  } catch (e) {
    console.warn("ensureCoverDir error:", e);
  }
}

// 이미지를 표지 라이브러리에 저장 (레거시 API)
// 🔧 v3.5.1: content:// URI 지원 강화 - 여러 방법 시도
async function saveCoverToLibrary(sourceUri, compressionLevel = "light", ext = "jpg") {
  // 🔧 v3.5.3: 에러 수집 + 파일 존재 확인 + 진단 강화
  const errors = [];
  try {
    await ensureCoverDir();
    
    // 소스 파일 존재 확인
    try {
      const srcInfo = await FileSystem.getInfoAsync(sourceUri);
      if (!srcInfo.exists) {
        return { error: "소스 파일 없음: " + sourceUri.substring(0, 60) };
      }
    } catch (infoErr) {
      errors.push("존재확인실패: " + infoErr.message);
      // 계속 진행 (content:// URI는 getInfoAsync가 실패할 수 있음)
    }
    
    const id = uuid();
    const fileName = `${id}.${ext}`;
    const destUri = COVER_DIR + fileName;
    
    let success = false;
    
    // 방법 1: copyAsync
    try {
      await FileSystem.copyAsync({ from: sourceUri, to: destUri });
      success = true;
    } catch (e1) {
      errors.push("copy: " + e1.message);
    }
    
    // 방법 2: downloadAsync — 🔧 v7.44.7: UA + Referer(원본 호스트) 헤더 첨부(일부 CDN이 헤더 없는 요청 차단).
    if (!success) {
      try {
        const origin = (String(sourceUri).match(/^(https?:\/\/[^/]+)/) || [])[1];
        const dlHeaders = /^https?:\/\//i.test(String(sourceUri))
          ? { "User-Agent": SCRAPER_UA, ...(origin ? { "Referer": origin + "/" } : {}) }
          : undefined;
        const r = await FileSystem.downloadAsync(sourceUri, destUri, dlHeaders ? { headers: dlHeaders } : undefined);
        if (r.status === 200) success = true;
        else errors.push("download: status=" + r.status);
      } catch (e2) {
        errors.push("download: " + e2.message);
      }
    }
    
    // 방법 3: base64 read/write
    if (!success) {
      try {
        const b64 = await FileSystem.readAsStringAsync(sourceUri, {
          encoding: FileSystem.EncodingType.Base64,
        });
        await FileSystem.writeAsStringAsync(destUri, b64, {
          encoding: FileSystem.EncodingType.Base64,
        });
        success = true;
      } catch (e3) {
        errors.push("base64: " + e3.message);
      }
    }
    
    if (!success) {
      return { error: errors.join(" | ") };
    }
    
    // 복사 후 확인
    const destInfo = await FileSystem.getInfoAsync(destUri);
    if (!destInfo.exists) {
      return { error: "복사 후 파일 없음" };
    }
    
    return {
      id,
      file_path: destUri,
      file_size: destInfo.size || 0,
    };
  } catch (e) {
    return { error: "전체: " + e.message };
  }
}

/**
 * 📷 이미지 압축/리사이즈 후 저장 (명대사 이미지용)
 * expo-image-manipulator로 리사이즈 + 압축 후 covers 디렉토리에 저장
 * @param sourceUri - ImagePicker에서 받은 원본 URI
 * @param maxSize - 긴 변 최대 크기 (px). null이면 리사이즈 스킵
 * @param quality - JPEG 압축 품질 (0~1)
 * @param ext - 파일 확장자
 * @returns { id, file_path, file_size } 또는 { error }
 */
// 🆕 v7.28.22: 이미지 압축/저장 진행 표시 — 여러 호출처(명대사·갤러리 이미지 등)를 한 번에 커버.
//   모듈 콜백(setImageBusyCallback)으로 컴포넌트에 begin/end를 알려 작은 오버레이를 띄움.
let _imageBusyCount = 0;
let _imageBusyCb = null;
function setImageBusyCallback(cb) { _imageBusyCb = cb; }
function _notifyImageBusy() { if (_imageBusyCb) { try { _imageBusyCb(_imageBusyCount > 0); } catch {} } }

async function compressAndSaveImage(sourceUri, maxSize, quality, ext = "jpg") {
  _imageBusyCount++; _notifyImageBusy();
  try { return await _compressAndSaveImageImpl(sourceUri, maxSize, quality, ext); }
  finally { _imageBusyCount = Math.max(0, _imageBusyCount - 1); _notifyImageBusy(); }
}

async function _compressAndSaveImageImpl(sourceUri, maxSize, quality, ext = "jpg") {
  try {
    // GIF는 압축 스킵 (애니메이션 손실 방지)
    if (ext === "gif") {
      return await saveCoverToLibrary(sourceUri, "original", ext);
    }

    // 출력 포맷 결정: PNG 입력은 PNG 유지, 그 외(HEIC/WebP 포함)는 JPEG로 변환
    const isPng = ext === "png";
    const format = isPng ? ImageManipulator.SaveFormat.PNG : ImageManipulator.SaveFormat.JPEG;
    const outputExt = isPng ? "png" : "jpg"; // 실제 출력 포맷에 맞는 확장자

    // 리사이즈: width만 지정하여 비율 유지 (height는 자동 계산)
    // 가로 이미지: width=800 → height 비율 자동 축소
    // 세로 이미지: width=800이면 원본 width가 이미 작을 수 있음 → 축소 안 됨 (upscale은 아래서 방지)
    // ※ width+height 동시 지정하면 비율 무시하고 강제 리사이즈되므로 width만 사용
    const actions = [];
    if (maxSize) {
      actions.push({ resize: { width: maxSize } });
    }

    const result = await ImageManipulator.manipulateAsync(
      sourceUri,
      actions,
      { compress: quality, format }
    );

    // 압축된 파일을 covers 디렉토리로 이동
    const saved = await saveCoverToLibrary(result.uri, "original", outputExt);

    // 임시 파일 정리 (manipulateAsync가 캐시에 생성)
    if (result.uri !== sourceUri) {
      FileSystem.deleteAsync(result.uri, { idempotent: true }).catch(() => {});
    }

    return saved;
  } catch (e) {
    console.warn("[compressAndSaveImage] 실패, JPEG 재인코딩 폴백:", e.message);
    // 🛡️ FIX: 원본 ext 그대로 저장하면 HEIC 등 RN이 못 그리는 포맷이 깨진 채 저장됨.
    //   먼저 리사이즈 없이 JPEG로만 재인코딩 시도(리사이즈/메모리 실패였다면 성공) → 렌더 가능.
    //   그것도 실패(예: 코덱 디코딩 불가)하면 최후로 원본 저장.
    try {
      const jpg = await ImageManipulator.manipulateAsync(sourceUri, [], {
        compress: quality, format: ImageManipulator.SaveFormat.JPEG,
      });
      const saved = await saveCoverToLibrary(jpg.uri, "original", "jpg");
      if (jpg.uri !== sourceUri) FileSystem.deleteAsync(jpg.uri, { idempotent: true }).catch(() => {});
      return saved;
    } catch (e2) {
      console.warn("[compressAndSaveImage] JPEG 재인코딩도 실패, 원본 저장:", e2.message);
      return await saveCoverToLibrary(sourceUri, "original", ext);
    }
  }
}

// 표지 라이브러리에서 이미지 삭제 (레거시 API)
async function deleteCoverFromLibrary(filePath) {
  try {
    const fileInfo = await FileSystem.getInfoAsync(filePath);
    if (fileInfo.exists) {
      await FileSystem.deleteAsync(filePath, { idempotent: true });
    }
  } catch (e) {
    console.warn("deleteCoverFromLibrary error:", e);
  }
}

// 표지 라이브러리 전체 용량 계산 (레거시 API)
async function getCoverLibrarySize() {
  try {
    await ensureCoverDir();
    const dirInfo = await FileSystem.getInfoAsync(COVER_DIR);
    if (!dirInfo.exists) return 0;
    
    const files = await FileSystem.readDirectoryAsync(COVER_DIR);
    let totalSize = 0;
    
    for (const fileName of files) {
      try {
        const fileInfo = await FileSystem.getInfoAsync(COVER_DIR + fileName);
        if (fileInfo.exists && fileInfo.size) {
          totalSize += fileInfo.size;
        }
      } catch (e) {
        // 개별 파일 오류는 무시
      }
    }
    return totalSize;
  } catch (e) {
    console.warn("getCoverLibrarySize error:", e);
    return 0;
  }
}

// 용량 포맷팅 헬퍼
function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  return (bytes / (1024 * 1024 * 1024)).toFixed(2) + " GB";
}

