// Chip: areEqual로 label/active만 비교 (onPress 변경 무시)
const Chip = memo(
  ({ label, active, onPress, value, onToggle }) => (
    <TouchableOpacity
      onPress={value !== undefined && onToggle ? () => onToggle(value) : onPress}
      style={{
        paddingVertical: 8,
        paddingHorizontal: 12,
        borderRadius: 999,
        backgroundColor: active ? C.primary : C.chip,
        marginRight: 8,
        marginBottom: 8,
      }}
    >
      <Text style={{ color: active ? "#fff" : C.text, fontWeight: "600" }}>
        {label}
      </Text>
    </TouchableOpacity>
  ),
  (prev, next) => prev.label === next.label && prev.active === next.active && prev.value === next.value
);
const PrimaryButton = memo(({ title, onPress, style, disabled }) => (
  <TouchableOpacity
    onPress={onPress}
    disabled={disabled}
    style={[
      {
        backgroundColor: disabled ? "#9ca3af" : C.primary,
        borderRadius: 14,
        paddingVertical: 14,
        alignItems: "center",
        opacity: disabled ? 0.6 : 1,
      },
      style,
    ]}
  >
    <Text style={{ color: "#fff", fontSize: 17, fontWeight: "700" }}>
      {title}
    </Text>
  </TouchableOpacity>
));
const OutlineButton = memo(({ title, onPress, style, color = C.sub }) => (
  <TouchableOpacity
    onPress={onPress}
    style={[
      {
        borderRadius: 12,
        paddingVertical: 12,
        paddingHorizontal: 16, // 🔧 v3.4.7: 가로 패딩 추가
        alignItems: "center",
        borderWidth: 1,
        borderColor: color,
      },
      style,
    ]}
  >
    <Text style={{ color, fontSize: 15, fontWeight: "700" }}>{title}</Text>
  </TouchableOpacity>
));
// 🆕 v7.4.5 headerRight: title 우측 액션 슬롯 (optional). 미전달 시 기존과 동일 렌더.
const Section = ({ title, headerRight, hideTitle, children }) => (
  <View
    style={{
      backgroundColor: C.card,
      borderRadius: 16,
      padding: 16,
      marginBottom: 16,
      borderWidth: 1,
      borderColor: C.line,
    }}
  >
    {/* 🆕 v7.4.10: hideTitle prop — 순위탭 export 중 title row+spacer 숨김(카드 위주 출력).
        기본값 falsy → 149+ 기존 호출 backward compat. */}
    {!hideTitle && (
      <>
        <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center" }}>
          <Text style={{ fontWeight: "800", fontSize: 18, color: C.text, flex: 1 }}>
            {title}
          </Text>
          {headerRight ? <View style={{ marginLeft: 8 }}>{headerRight}</View> : null}
        </View>
        <View style={{ height: 8 }} />
      </>
    )}
    {children}
  </View>
);

