  autoApproveMinWins: 10,           // 자동 승인 최소 승수
  autoApproveMaxLosses: 3,          // 자동 승인 최대 패수
  autoApproveMinMatches: 15,        // 자동 승인 최소 매칭 수
  showReviewBanner: true,           // 홈 화면 검토 배너 표시
  undoStackSize: 30,                // 되돌리기 스택 크기
