  // 🔧 v3.5.11 성능: init 중복 호출 방지
  const initLoadedRef = useRef(false);
  
  async function loadList(sortKey, sortDir, _trigger) {
    // P1: init 트리거 중복 방지 (StrictMode/더블 마운트 대응)
    if (_trigger === "init") {
      if (initLoadedRef.current) {
        PerfMonitor.beginFunc("loadList", "init-skipped"); // 🔬
        PerfMonitor.endFunc("loadList"); // 🔬
        return;
      }
      initLoadedRef.current = true;
    }
    // 🔧 v3.5.15c: 동시 실행 방지 — 이전 loadList가 아직 DB 읽기 중이면 스킵
    // 매칭 중 decide()→loadList + deferSetAppMeta→loadList + 화면전환→loadList 등
    // 여러 소스에서 동시 호출될 수 있음. 중복 SELECT * FROM novels는 DB 부하만 증가시킴
    if (loadListRunningRef.current) {
      PerfMonitor.beginFunc("loadList", (_trigger || "unknown") + "-concurrent-skip"); // 🔬
      PerfMonitor.endFunc("loadList"); // 🔬
      return;
    }
    loadListRunningRef.current = true;
    Breadcrumbs.db("loadList", _trigger || "unknown");
    PerfMonitor.beginFunc("loadList", _trigger || "unknown"); // 🔬 v3.5.9b
    try {
      const sk = sortKey ?? homeSortKey;
      const sd = sortDir ?? homeSortDir;
      let orderBy = `pinned DESC, rating ${sd}, created_at ASC`;
      if (sk === "title") {
        orderBy = `pinned DESC, title COLLATE NOCASE ${sd}`;
      } else if (sk === "created") {
        orderBy = `pinned DESC, created_at ${sd}`;
      } else if (sk === "read") {
        orderBy = `pinned DESC, read_count ${sd}, rating DESC`;
      }
      const rows = await all(`SELECT * FROM novels ORDER BY ${orderBy};`);
      PerfMonitor.stepFunc("loadList", "SQL"); // 🔬 v3.5.9b
      // 🛡️ v3.5.6: 숫자 필드 정규화 (null → 기본값, 하위 렌더링 크래시 방지)
      const safeRows = (rows || []).map(normalizeNovel);
      PerfMonitor.stepFunc("loadList", "normalize"); // 🔬 v3.5.9b
      // 🔧 v7.6.0 (포트 v3.10.0): ratio 모드 — 정렬 + 누적 비율 사전 계산
      if (globalTierConfig?.mode === "ratio") {
        try { globalRatioTierMap = computeRatioTierMap(safeRows, globalTierConfig); }
        catch (e) { console.warn("[ratio] computeRatioTierMap 실패:", e?.message); globalRatioTierMap = new Map(); }
      } else {
        globalRatioTierMap = new Map();
      }
      // 🆕 v7.22.0: hybrid/manual 모드 — 티어 내 순위 비율 사전 계산(getPrefScore가 manual_order 반영)
      if (globalTierConfig?.mode === "hybrid" || globalTierConfig?.mode === "manual") {
        try { globalTierRankMap = computeTierRankMap(safeRows, globalTierConfig); }
        catch (e) { console.warn("[tierRank] computeTierRankMap 실패:", e?.message); globalTierRankMap = new Map(); }
      } else {
        globalTierRankMap = new Map();
      }
      setList(safeRows);
      updateTagUsageCounts(safeRows); // 🏷️ 태그 사용 빈도 업데이트
      PerfMonitor.stepFunc("loadList", "tagCount"); // 🔬 v3.5.9b
      // 🔧 v3.5.15: 매칭 캐시 무효화 (loadList는 작품 추가/삭제/편집 후 호출되므로)
      invalidateMatchCache();
      // 🔬 v3.5.9: 상태 크기 스냅샷
      if (PerfMonitor.enabled) {
        PerfMonitor.snapshotState({
          novels: safeRows.length,
          customTags: customTags.length,
          // 🔧 v7.6.0 (포트 v3.9.2): comboTags 진단 누락 수정
          comboTags: (customComboTraits?.length || 0) + (customComboTargets?.length || 0),
          coverImages: coverLibrary?.length || 0,
        });
      }
      // 🔧 v3.5.14: 매칭 중 loadMatchStats 디바운스 (900ms 쿼리 중복 방지)
      // "op"(매칭 결과) 시 3초 지연 — 연속 매칭 시 마지막 1회만 실행
      // 기타 트리거는 500ms 지연 (UI 응답성 유지하면서 동시 DB 부하 감소)
      if (matchStatsTimerRef.current) clearTimeout(matchStatsTimerRef.current);
      matchStatsTimerRef.current = setTimeout(() => {
        loadMatchStats().catch(() => {});
        matchStatsTimerRef.current = null;
      }, _trigger === "op" ? 3000 : 500);
      PerfMonitor.endFunc("loadList"); // 🔬 v3.5.9b
      loadListRunningRef.current = false; // 🔧 v3.5.15c
    } catch (e) {
      console.warn("loadList 오류:", e);
      PerfMonitor.logError("loadList", e); // 🔬
      PerfMonitor.endFunc("loadList"); // 🔬 v3.5.9b
      loadListRunningRef.current = false; // 🔧 v3.5.15c
      setList([]);
    }
  }

  // 🆕 핀 토글 (🔧 stale closure 방지를 위해 일반 함수 사용)
  async function togglePin(id, currentPinned) {
    await exec("UPDATE novels SET pinned=? WHERE id=?", [currentPinned ? 0 : 1, id]);
    await loadList(undefined, undefined, "pin");
  }

  // 🔧 v7.13.1: 의심 표시 시 후보 유무를 먼저 검사 — 후보 0이면 매칭이 안 뜨므로 이유를 안내하고
  //   큐 등록을 생략. 후보가 있을 때만 등록. (v7.13.3: 큐 INSERT 자체를 막던 레거시 'type' 컬럼이
  //   "매칭이 한 번도 안 뜨던" 근본 원인이었고 별도 마이그레이션으로 수정함.)
  async function flagSuspect(id, direction) {
    try {
      await exec("UPDATE novels SET user_flagged_suspect=1 WHERE id=?", [id]);
      const cands = await getCandidatesForVerification(id, direction, 1);
      await loadList(undefined, undefined, "v7-userflag");
      if (!cands || cands.length === 0) {
        const self = await first("SELECT manual_tier FROM novels WHERE id=?", [id]);
        const noTier = !self?.manual_tier;
        const dirWord = direction === "underrated" ? "위쪽" : "아래쪽";
        Alert.alert(
          "🔍 의심 표시됨 (지금은 점검 불가)",
          noTier
            ? "이 작품은 아직 티어가 지정되지 않아 자리 점검을 할 수 없어요.\n순위 탭에서 티어를 먼저 지정하면 점검 대상이 됩니다."
            : `${dirWord}에 비교할 작품이 없어 점검을 진행할 수 없어요.\n이미 끝자리이거나 그 방향에 작품이 없습니다.`
        );
        return;
      }
      await enqueueVerification(id, "user_flag", direction, "user_toggle");
      Alert.alert("🔍 의심 표시됨", "점검 대기에 추가되었습니다.\n매칭 탭에서 점검을 시작할 수 있습니다.");
    } catch (e) {
      console.warn("[v7.13.1] flagSuspect 오류:", e?.message);
    }
  }

  // 🆕 v7.4.13: 사용자 명시 의심 표시 토글 (hybrid 모드 전용).
  // ON: 방향 선택 dialog → user_flagged_suspect=1 + enqueueVerification(user_flag) → priority 다축 통합으로 큐 상위 자동 노출.
  // OFF: user_flagged_suspect=0. 큐 row는 자연 처리(다른 트리거가 살아있으면 priority 재계산 시 강등).
  // 양방향 "auto"는 inflection 알고리즘과 호환되지 않아 사용자가 방향 명시 (높아져야/낮아져야).
  async function toggleSuspect(id, currentFlag, title) {
    if (currentFlag) {
      // OFF
      try {
        await exec("UPDATE novels SET user_flagged_suspect=0 WHERE id=?", [id]);
        await loadList(undefined, undefined, "v7-userflag");
      } catch (e) {
        console.warn("[v7.4.13] toggleSuspect OFF 오류:", e?.message);
      }
      return;
    }
    // ON: 방향 선택 후 enqueue
    Alert.alert(
      "🔍 의심 표시",
      `"${title}"의 자리가 어떻게 의심되나요?`,
      [
        { text: "취소" },
        {
          text: "⬆️ 더 높을 듯",
          onPress: () => flagSuspect(id, "underrated"),
        },
        {
          text: "⬇️ 더 낮을 듯",
          onPress: () => flagSuspect(id, "overrated"),
        },
      ]
    );
  }

  // 📰 v3.0: 최신 변화 기록 추가 헬퍼
  // type: "new" | "award" | "tier_change" | "tier_review" | "read_count" | "title_change" | "auto_tier"
  // 📅 v3.0.3: customTimestamp 옵션 추가 (날짜 수동 설정 시 해당 시점 기록용)
  const addRecentChange = useCallback(async (novelId, novelTitle, type, details = {}, customTimestamp = null) => {
    const change = {
      id: uuid(),
      novelId,
      novelTitle,
      type,
      details, // { from, to, awardName, delta, etc. }
      timestamp: customTimestamp || Date.now(),
    };
    
    setRecentChanges(prev => {
      const updated = [change, ...prev].slice(0, 500); // 최대 500개 유지
      // 🔧 React 18+ 배칭 대응: setTimeout으로 렌더 이후 저장
      safeDefer(() => deferSetAppMeta("recent_changes", updated));
      return updated;
    });
  }, []);

  // 🆕 v7.28.65: 랭크 이동(티어/순위)을 최신 기록에 남김 — '최신' 필터의 '랭크 이동' 신호.
  //   동일 작품의 직전 랭크이동(tier_change/order_change)이 1시간 내면 합쳐 최신화(▲/▼ 연타 홍수 방지).
  //   type: "tier_change"(교차 티어, details {from,to}) | "order_change"(같은 티어 순위, details {dir}).
  const recordRankChange = useCallback((novelId, novelTitle, type, details = {}) => {
    if (!novelId) return;
    setRecentChanges(prev => {
      const now = Date.now();
      const COALESCE_MS = 60 * 60 * 1000;
      const i = prev.findIndex(c => c.novelId === novelId && (c.type === "tier_change" || c.type === "order_change"));
      let updated;
      if (i !== -1 && now - (prev[i].timestamp || 0) < COALESCE_MS) {
        const old = prev[i];
        const merged = {
          ...old, type, novelTitle, timestamp: now,
          details: { ...old.details, ...details, from: old.details?.from ?? details.from, count: (old.details?.count || 1) + 1 },
        };
        updated = [merged, ...prev.slice(0, i), ...prev.slice(i + 1)];
      } else {
        updated = [{ id: uuid(), novelId, novelTitle, type, details: { ...details, count: 1 }, timestamp: now }, ...prev].slice(0, 500);
      }
      safeDefer(() => deferSetAppMeta("recent_changes", updated));
      return updated;
    });
  }, []);

  // 📰 v3.0: 최신 변화 기록 전체 삭제
  const clearRecentChanges = useCallback(async () => {
    Alert.alert(
      "확인",
      "모든 최신 변화 기록을 삭제할까요?",
      [
        { text: "취소" },
        { 
          text: "삭제", 
          style: "destructive",
          onPress: async () => {
            setRecentChanges([]);
            await setAppMeta("recent_changes", []);
            Alert.alert("완료", "최신 변화 기록이 삭제되었습니다.");
          }
        }
      ]
    );
  }, []);

  const togglePlatform = useCallback((p) => {
    setPlatforms((prev) =>
      prev.includes(p) ? prev.filter((x) => x !== p) : [...prev, p]
    );
  }, []);

  // 🆕 v7.28.50: 신규 작품 등록 폼 전체 초기화 (재사용: addNovel 성공 후 + 등록란 비우기 버튼)
  // deleteQuoteImages=true: 추적 중인 명대사 배경 이미지 파일까지 삭제(고아 방지).
  //   등록 성공 시엔 false — 저장된 작품이 파일을 사용하므로 추적만 해제하고 파일은 유지.
  function clearNovelForm({ deleteQuoteImages = false } = {}) {
    setTitle("");
    setAuthor("");
    setTags("");
    setPlatforms([]);
    setNote("");
    setMemorableQuote([]); // 💬 인상깊은 문장 초기화
    setRegQuoteStyleIdx(-1); // 🆕 v7.9.1: 서식 패널 초기화
    if (deleteQuoteImages && regQuoteImagesRef.current.length > 0) {
      // 📷 v3.6.2 패턴: 등록 안 하고 비우면 추가했던 명대사 이미지가 고아가 되므로 삭제
      for (const uri of regQuoteImagesRef.current) {
        FileSystem.deleteAsync(uri, { idempotent: true }).catch(() => {});
      }
    }
    regQuoteImagesRef.current = []; // 📷 추적 해제 (성공=파일 유지 / 비우기=위에서 삭제)
    setReadCount("");
    setTotalEpisodes("");
    setRereadCount("1"); // 다회독 초기화
    setNewStatus("reading");
    setNewWorkStatus("ongoing");
    setNewCoverImage("");
    setNewLink("");
    setNewMajorGenre([]);
    setNewSubGenre([]);
    setNewTagData([]); // 🏷️ v5.0
    setNewGaidenStatus("none");
    setNewGaidenReadCount("");
    setNewGaidenTotalEpisodes("");
    setNewCompletedAt(0); setNewGaidenStartAt(0); setNewGaidenCompletedAt(0); // 🆕 v7.44.6
    setNewManualTier(""); // 🆕 v6.0: 등록 시 티어 선택 초기화
    setNewStartYear(0); // 🔧 v7.6.0 (포트 v3.12.0)
    setNewEndYear(0);
  }
  // 🆕 v7.28.50: 홈탭 등록란 비우기 버튼 — 입력 내용이 있으면 확인 후 초기화
  function confirmClearNovelForm() {
    const hasContent = !!(
      title.trim() || author.trim() || tags.trim() || note.trim() ||
      platforms.length || readCount.trim() || totalEpisodes.trim() ||
      newLink.trim() || newCoverImage || memorableQuote.length ||
      newMajorGenre.length || newSubGenre.length || newTagData.length ||
      newManualTier || newGaidenReadCount.trim() || newGaidenTotalEpisodes.trim()
    );
    if (!hasContent) { clearNovelForm({ deleteQuoteImages: true }); return; }
    Alert.alert("등록란 비우기", "입력한 내용을 모두 지울까요?", [
      { text: "취소", style: "cancel" },
      { text: "비우기", style: "destructive", onPress: () => clearNovelForm({ deleteQuoteImages: true }) },
    ]);
  }

  async function addNovel() {
    const _pt = PerfMonitor.enabled ? Date.now() : 0; // 🔬
    const t = (title || "").trim();
    if (!t) {
      Alert.alert("알림", "제목은 필수입니다.");
      return;
    }
    // 🛡️ FIX: 동기 ref 재진입 가드 — isLoading은 비동기 state라 같은 프레임 더블탭에 stale(중복 INSERT).
    //   ref는 진입 즉시 동기 설정 → 같은 프레임 두 번째 호출 차단. (각 exit에서 false로 리셋)
    if (addNovelBusyRef.current) return;
    addNovelBusyRef.current = true;

    setIsLoading(true);

    try {
      // 🔧 v3.5.9: 본 목록 + 예정 목록 양쪽 중복 체크
      const dup = await first("SELECT id FROM novels WHERE title=?", [t]);
      const dupPlanned = await first("SELECT id FROM planned_novels WHERE title=?", [t]);
      if (dup || dupPlanned) {
        addNovelBusyRef.current = false;
        setIsLoading(false);
        Alert.alert("알림", dup ? "같은 제목이 이미 있습니다." : "예정 목록에 같은 제목이 있습니다.");
        return;
      }
      
      Breadcrumbs.action("novel_add", t);
      // 🏷️ 대장르/부장르 자동 감지 (설정 안 된 경우)
      const detectedGenres = detectGenres(tags);
      // 배열로 저장 (선택된 것이 있으면 그것을, 없으면 자동 감지 결과)
      const finalMajorGenre = newMajorGenre.length > 0 
        ? JSON.stringify(newMajorGenre) 
        : (detectedGenres.majorGenre ? JSON.stringify([detectedGenres.majorGenre]) : "");
      const finalSubGenre = newSubGenre.length > 0 
        ? JSON.stringify(newSubGenre) 
        : (detectedGenres.subGenre ? JSON.stringify([detectedGenres.subGenre]) : "");
      
      const id = uuid();
      const now = Date.now();
      
      // 🏷️ v5.0: tag_data 생성
      const tagDataJson = newTagData && newTagData.length > 0
        ? JSON.stringify(newTagData)
        : "";

      // 🆕 v6.0: 모드별 manual_tier 결정 (한 번 계산하여 INSERT + manual_order 산출에 재사용)
      const initialManualTier = (() => {
        if (globalTierConfig.mode === "manual") return newManualTier || globalTierConfig.defaultTier;
        if (globalTierConfig.mode === "hybrid" && newManualTier) return newManualTier;
        if (globalTierConfig.mode === "match" && globalTierConfig.allowRegistrationTier && newManualTier) return newManualTier;
        return null;
      })();

      // 🆕 v7.0.1 (N6 fix): 신규 작품 manual_order = 같은 tier 최대 + 100 (collision 방지)
      let initialManualOrder = 0;
      try {
        if (initialManualTier) {
          const maxRow = await first("SELECT MAX(manual_order) AS m FROM novels WHERE manual_tier=?", [initialManualTier]);
          initialManualOrder = (Number(maxRow?.m) || 0) + 100;
        } else {
          // manual_tier 미설정 시 NULL 그룹 (Unrated) 안에서 max+100
          const maxRow = await first("SELECT MAX(manual_order) AS m FROM novels WHERE manual_tier IS NULL OR manual_tier=''");
          initialManualOrder = (Number(maxRow?.m) || 0) + 100;
        }
      } catch (e) {
        console.warn("[v7.0] addNovel manual_order 계산 실패:", e?.message);
      }

      // 🛠️ v7.3.2: INSERT + read_count_baseline UPDATE를 단일 트랜잭션으로 묶음
      // 이전: 두 단계 exec 사이에 SQLITE_BUSY 발생 시 baseline=0 잔존 → 누적 트래킹 mass-fire 위험.
      // convertPlannedToNovel(v7.3.1) 패턴과 일치.
      const _initialReadCount = Number(readCount) || 0;
      await execBatch([
        {
          sql: `INSERT INTO novels (id,title,author,tags,platforms,note,read_count,rating,rd,wins,losses,match_count,tier,created_at,awards,total_episodes,status,pinned,cover_image,link,work_status,read_count_updated_at,major_genre,sub_genre,gaiden_status,gaiden_read_count,gaiden_total_episodes,reread_count,tag_data,memorable_quote,aliases,manual_tier,manual_order,read_count_baseline,start_year,end_year,completed_at,gaiden_start_at,gaiden_completed_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);`,
          params: [
            id,
            t,
            author.trim(),
            deduplicateTagString(tags) || "", // 🔧 v3.5.14: 작품 내 태그 중복 제거
            JSON.stringify(mergePlatformFromLink(platforms, newLink)), // 🆕 v7.28.64: 링크 플랫폼 연재처 자동 병합
            note.trim(),
            _initialReadCount,
            globalTierConfig.defaultRating || 1500, // 🆕 v6.0: config 기반 기본 레이팅
            350,
            0,
            0,
            0,
            globalTierConfig.defaultTier || "C", // 🆕 v6.0: config 기반 기본 티어
            now,
            "",
            Number(totalEpisodes) || 0,
            newStatus,
            0,
            newCoverImage,
            newLink.trim(),
            newWorkStatus,
            now,
            finalMajorGenre,
            finalSubGenre,
            newGaidenStatus,
            Number(newGaidenReadCount) || 0,
            Number(newGaidenTotalEpisodes) || 0,
            Math.max(1, Number(rereadCount) || 1), // 📚 다회독 카운트
            tagDataJson, // 🏷️ v5.0
            serializeQuotes(memorableQuote), // 💬 인상깊은 문장 (텍스트+이미지)
            "", // aliases (빈 값)
            initialManualTier,
            initialManualOrder, // 🆕 v7.0.1 (N6 fix)
            _initialReadCount, // 🆕 v7.0.15: read_count_baseline = 초기 read_count
            Number(newStartYear) || 0, // 🔧 v7.6.0 (포트 v3.12.0): 연재 시작 연도
            Number(newEndYear) || 0,   // 🔧 v7.6.0 (포트 v3.12.0): 연재 종료 연도
            Number(newCompletedAt) || 0,      // 🆕 v7.44.6: 본편 완결일
            Number(newGaidenStartAt) || 0,    // 🆕 v7.44.6: 외전 시작일
            Number(newGaidenCompletedAt) || 0,// 🆕 v7.44.6: 외전 완결일
          ],
        },
      ]);
      // 🔧 v3.5.9: 텍스트 입력 태그 → customTags 동기화 (태그 관리 모달 연동)
      syncTagsToCustom(tags.trim());
      // 🆕 v7.28.50: clearNovelForm 재사용 — 등록 성공이므로 명대사 이미지 파일은 유지(추적만 해제)
      clearNovelForm();
      await loadList(undefined, undefined, "register");
      await refreshDailyRecommendation(false);
      
      // 🖼️ v3.4.5: 표지 라이브러리 상태 업데이트
      if (newCoverImage) {
        await applyNovelCover(id, newCoverImage, null);
        await loadCoverLibrary();
      }
      
      // 📰 v3.0: 신규 등록 기록
      let majorGenreText = "-";
      try {
        if (finalMajorGenre) {
          const parsed = JSON.parse(finalMajorGenre);
          if (Array.isArray(parsed)) majorGenreText = parsed.join(", ");
        }
      } catch {}
      await addRecentChange(id, t, "new", {
        author: author.trim() || "-",
        majorGenre: majorGenreText
      });

      // 🆕 v7.0: hybrid 모드 — 신규 등록 작품을 검증 큐에 추가 (manual_tier 설정된 경우만)
      // 🆕 v7.0.3: 최상위 tier에 등록 시 underrated 후보 풀이 비어 무의미한 no_candidates 즉시 finalize
      // → 의미있는 방향(overrated, 아래쪽 검증)으로 큐잉. 단, 단일 tier 시스템이면 enqueue 자체 생략.
      // 🆕 v7.0.6 (M6): 최하위 tier(idx===order.length-1)도 underrated 큐잉 — 이전 idx<order.length-1 조건이
      // 최하위를 제외해 검증 사이클 통째 누락. 위쪽으로 비교는 가능하므로 underrated가 정상 의미.
      // 🆕 v7.5.0 (B1): 신작 추가 시 같은 tier 아래 인접 1작 conflict 캐스케이드 + conflict_hits 누적
      if (globalTierConfig.mode === "hybrid" && newManualTier) {
        try {
          const order = getActiveTierOrder(globalTierConfig);
          const idx = order.indexOf(newManualTier);
          if (idx === 0 && order.length > 1) {
            // 최상위 tier — 위쪽 비교 불가, 아래쪽으로 검증
            await enqueueVerification(id, "new", "overrated", "addNovel");
          } else if (idx > 0) {
            // 중간/최하위 tier — 위쪽으로 검증 (default). idx===order.length-1 (최하위)도 포함.
            await enqueueVerification(id, "new", "underrated", "addNovel");
          }
          propagateRankSuspicion(id).catch(() => {}); // 🆕 v7.17.0 증거①: 신작 삽입 인접권 의심도 전파
          // idx === -1(비활성) 또는 단일 tier(idx===0 && length===1) 시스템 → enqueue 생략

          // 🆕 v7.5.0 (B1): 같은 tier 내 manual_order 바로 아래 1작에 conflict cascade
          // 신작은 MAX+100으로 삽입되므로 위쪽 인접은 없음 — 아래만 후보
          try {
            const adjacent = await first(
              `SELECT id FROM novels WHERE manual_tier=? AND id != ? AND manual_order < ?
               ORDER BY manual_order DESC LIMIT 1`,
              [newManualTier, id, initialManualOrder]
            );
            if (adjacent?.id) {
              await exec(
                "UPDATE novels SET conflict_hits = conflict_hits + 1 WHERE id=?",
                [adjacent.id]
              );
              await enqueueVerification(adjacent.id, "conflict", "overrated", "addNovel_cascade");
            }
            // 결과 0건이면 cascade 스킵 (빈 tier 또는 신작이 유일)
          } catch (cascadeErr) {
            console.warn("[v7.5.0 B1] addNovel cascade 실패:", cascadeErr?.message);
          }
        } catch (e) {
          console.warn("[v7.0] new 검증 큐 INSERT 실패:", e?.message);
        }
      }

      if (_pt) PerfMonitor.trackFunc("addNovel", Date.now() - _pt); // 🔬
      // 🆕 v7.20.12: manual 모드 — 추가 직후 '비교로 배치' 제안 (사용자 선택, 비교 대상 없으면 startPlacement가 안내)
      if (globalTierConfig.mode === "manual") {
        Alert.alert("작품 추가됨", "지금 비교로 자리를 찾을까요?\n(몇 번의 A/B 선택으로 자동 배치)", [
          { text: "나중에", style: "cancel" },
          { text: "🔍 지금 배치", onPress: () => { startPlacement(id); } },
        ]);
      } else {
        Alert.alert("완료", "작품이 추가되었습니다.");
      }
    } catch (e) {
      if (_pt) PerfMonitor.logError("addNovel", e); // 🔬
      console.warn("addNovel 오류:", e);
      // 📷 v3.6.2: 등록 실패 시 이미 저장된 명대사 이미지 파일 정리 (고아 방지)
      if (regQuoteImagesRef.current.length > 0) {
        for (const uri of regQuoteImagesRef.current) {
          FileSystem.deleteAsync(uri, { idempotent: true }).catch(() => {});
        }
        regQuoteImagesRef.current = [];
      }
      Alert.alert("오류", "작품 추가 중 오류가 발생했습니다.\n\n" + e.message);
    }
    addNovelBusyRef.current = false; // 🛡️ FIX: 성공·catch 모두 통과하는 최종 리셋
    setIsLoading(false);
  }


  // 🚫 v7.6.0 (포트 v3.16.0): 매칭 밴 토글
  // - UPDATE novels SET match_ban = ?
  // - 밴 시 hybrid 검증 큐 pending 항목 취소 (main 스키마: novel_id/state/processed_at)
  // - focus가 이 작품이면 해제
  // - invalidateMatchCache() + loadList() 동기화
  async function toggleMatchBan(id, ban) {
    try {
      await exec("UPDATE novels SET match_ban=? WHERE id=?", [ban ? 1 : 0, id]);
      if (ban) {
        try {
          // 🔧 v7.6.0: main의 tier_verification_queue 스키마에 맞춤
          // (포트 원본의 status/invalidated_at/subject_id 컬럼은 main에 없음 → state/processed_at/novel_id 사용)
          // 작품 삭제(removeNovel) 시 큐 취소와 동일 패턴
          await exec(
            `UPDATE tier_verification_queue SET state='cancelled', processed_at=? WHERE novel_id=? AND state='pending'`,
            [Date.now(), id]
          );
        } catch (e) { console.warn('[match_ban] queue cancel failed:', e?.message); }
        if (focusMatchNovel?.id === id) setFocusMatchNovel(null);
        // 🔧 v7.10.0: 밴 즉시성 — 화면의 현재 대결에 밴 작품이 포함되면 즉시 비움(removeNovel과 동일).
        //   안 그러면 밴 직후에도 그 대결을 그대로 판정해 밴 작품의 ELO가 갱신됨.
        if (pair && (pair.A?.id === id || pair.B?.id === id)) setPair(null);
      }
      invalidateMatchCache();
      await loadList(undefined, undefined, ban ? "match_ban_set" : "match_ban_unset");
    } catch (e) {
      console.warn('[match_ban] toggle failed:', e?.message);
      Alert.alert("오류", "매칭 밴 상태 변경에 실패했습니다.\n\n" + (e?.message || ""));
    }
  }

  async function removeNovel(id) {
    Alert.alert("확인", "정말로 이 작품을 삭제할까요? (대진 로그도 함께 삭제됩니다)", [
      { text: "취소" },
      {
        text: "삭제",
        style: "destructive",
        onPress: async () => {
          Breadcrumbs.action("novel_delete", id);
          setIsLoading(true);
          try {
            // 🔧 v7.49.17: DELETE 전 매칭 큐 drain (불변규칙 #3) — in-flight 수동 매칭 task가 이 작품을 참조 중이면
            //   삭제 후 그 task의 UPDATE/INSERT OR IGNORE matches가 고아 행을 되살리던 경합 방지(+이후 task는 !rawA 가드로 안전).
            if (!isMatchQueueIdle()) { try { await waitForMatchQueueDrain(3000); } catch {} }
            // 🖼️ v3.4.5: 삭제 전에 해당 작품의 표지 + 📷 v6.0.1: 명대사 이미지 가져오기
            // 🆕 v7.21.0: 되돌리기용 전체 행 + 매치 스냅샷 (SELECT * → undo 'novel_delete'가 작품+ELO 복원)
            const novel = await first("SELECT * FROM novels WHERE id=?", [id]);
            const coverPath = novel?.cover_image;
            let _undoMatches = [];
            try {
              _undoMatches = await all("SELECT * FROM matches WHERE a_id=? OR b_id=?", [id, id]);
            } catch (e) { console.warn("removeNovel 매치 스냅샷 실패:", e?.message); }
            
            // 🔄 v3.5.0: 상태 동기화 - 삭제 대상과 관련된 모든 상태 초기화
            if (pair && (pair.A?.id === id || pair.B?.id === id)) {
              setPair(null);
            }
            if (editItem?.id === id) {
              editOriginalSnapshotRef.current = null; // 🔧 v3.5.9: 삭제 시 스냅샷 정리
              updateEditItem(null);
              setEditOpen(false);
            }
            setDailyReco(prev => { // 🎯 v7.50.0: 배열 형태 — 해당 item만 제거
              if (!prev?.items) return prev;
              const f = prev.items.filter(it => it.novel?.id !== id);
              return f.length === prev.items.length ? prev : (f.length ? { ...prev, items: f } : null);
            });
            if (focusMatchNovel?.id === id) {
              setFocusMatchNovel(null);
            }
            // 🔧 v3.5.8: selectedIds에서도 제거
            if (selectedIdsRef.current.includes(id)) {
              setSelectedIds(prev => prev.filter(x => x !== id));
            }
            // 🆕 v7.2.3: 진행 중 verification 세션이 삭제 대상이면 abort
            // (이전: 세션이 deleted novel 참조 → 다음 decide() 시 candidate 미존재로 잠재 크래시)
            // 🛠️ v7.3.3: candidate 삭제도 abort 대상에 추가 — 기존엔 suspicion novel만 체크 → 후보 삭제 시
            // 시퀀스가 stale candidate를 계속 참조 → finalize blocker_id orphan + tier_validation_log orphan
            const _vs = verificationSessionRef.current;
            if (_vs && (_vs.queueRow?.novel_id === id || _vs.candidates?.some(c => c.id === id))) {
              setVerificationSession(null);
              verificationSessionIdRef.current = null;
            }

            // 🔧 v3.5.8: choice_logs도 함께 삭제 (고아 방지)
            // 🎨 v3.8.0: 갤러리 이미지 파일 삭제 (DB 삭제 전)
            try {
              const gImgs = await all("SELECT file_path FROM gallery_images WHERE novel_id=?", [id]);
              for (const g of gImgs) {
                await deleteCoverFromLibrary(g.file_path);
              }
            } catch (gErr) { console.warn("removeNovel gallery cleanup:", gErr); }

            await execBatch([
              { sql: "DELETE FROM choice_logs WHERE winner_id=? OR loser_id=?", params: [id, id] },
              { sql: "DELETE FROM matches WHERE a_id=? OR b_id=?", params: [id, id] },
              { sql: "DELETE FROM novel_folders WHERE novel_id=?", params: [id] },
              { sql: "DELETE FROM gallery_images WHERE novel_id=?", params: [id] }, // 🎨 v3.8.0
              // 🆕 v7.0.2: 하이브리드 검증 테이블 고아 정리 (FK CASCADE 미선언, 누적 시 통계 오염)
              { sql: "DELETE FROM tier_verification_queue WHERE novel_id=?", params: [id] },
              { sql: "DELETE FROM tier_validation_log WHERE novel_a_id=? OR novel_b_id=?", params: [id, id] },
              { sql: "DELETE FROM tier_repositioning_session WHERE novel_id=?", params: [id] },
              { sql: "UPDATE tier_repositioning_session SET blocker_id=NULL WHERE blocker_id=?", params: [id] },
              // 🆕 v7.0.8: trigger_fire_log 고아 정리
              { sql: "DELETE FROM trigger_fire_log WHERE novel_id=?", params: [id] },
              // 🆕 v7.3.0: v7.1 tier_inversion 패턴(novel:{id})은 id 참조 → 함께 정리
              // (다른 카테고리 tag/author/genre/award는 entity-keyed라 무관)
              { sql: "DELETE FROM preference_patterns WHERE pattern_key=?", params: [`novel:${id}`] },
              { sql: "DELETE FROM novels WHERE id=?", params: [id] },
            ]);
            // 🔧 v3.5.15e: 미플러시 choiceLog에서도 삭제 대상 제거 (고아 재삽입 방지)
            choiceLogQueue.pending = choiceLogQueue.pending.filter(l => l.winner_id !== id && l.loser_id !== id);
            
            // 🖼️ v3.4.5: 표지가 있었으면 상태를 미사용으로 변경
            if (coverPath) {
              await updateCoverStatus(coverPath, null, "unused");
              await loadCoverLibrary();
            }

            // 📷 v6.0.1: 명대사 이미지 파일 정리 (고아 방지)
            if (novel?.memorable_quote) {
              try {
                const quotes = parseQuotes(novel.memorable_quote);
                for (const q of quotes) {
                  if (isImageQuote(q)) {
                    FileSystem.deleteAsync(q.uri, { idempotent: true }).catch(() => {});
                  }
                  const _st = getQuoteStyle(q); // 🆕 v7.8.0: 텍스트 서식 배경이미지도 정리
                  if (_st && _st.bgImage) FileSystem.deleteAsync(_st.bgImage, { idempotent: true }).catch(() => {});
                }
              } catch {}
            }
            
            await rebuildAllFromMatches(tagAttributes);
            await loadList(undefined, undefined, "rebuild");
            await loadGalleryImages(); // 🎨 v3.8.0
            // 🆕 v7.21.0: 삭제 되돌리기 — 작품 행 + 매치 복원 (갤러리/명대사 이미지 파일은 물리 삭제되어 복구 불가)
            if (novel) {
              pushUndo('novel_delete', { novel, matches: _undoMatches }, `'${novel.title}' 삭제`);
            }
          } catch (e) {
            console.warn("removeNovel 오류:", e);
            Alert.alert("오류", "삭제 중 문제가 발생했습니다: " + (e.message || e));
          }
          setIsLoading(false);
        },
      },
    ]);
  }

  // ═══════════════════════════════════════════════════════════════════
  // 🧹 v3.5.5: 커스텀 초기화 시스템
  // ═══════════════════════════════════════════════════════════════════
  
